import { Timestamp } from "rxjs";
import router from "../router";
import store from "../store";
import axios from "axios";
preparePlantChart(data: object, min: number, max: number, mainColor: String, timeFormat: <mask>, start: Date, end: Date) {
      const opactiyColor = () => {
        let hex = mainColor.replace("#", "");

        if (hex.length === 3) {
          hex = `${hex[0]}${hex[0]}${hex[1]}${hex[1]}${hex[2]}${hex[2]}`;
        }

        const r = parseInt(hex.substring(0, 2), 16);
        const g = parseInt(hex.substring(2, 4), 16);
        const b = parseInt(hex.substring(4, 6), 16);

        return `rgba(${r},${g},${b},${60 / 100})`;
      };
      // console.log(data);
      return {
        data: {
          datasets: [
            {
              type: "line",
              data: data,
              borderWidth: 2,
              borderColor: mainColor,
              backgroundColor: opactiyColor,
              pointRadius: 0,
              order: 2,
            },
            {
              type: "line",
              data: [
                { x: start, y: min },
                { x: end, y: min },
              ],
              borderWidth: 1,
              borderColor: "rgba(235, 75, 0, 0.2)",
              backgroundColor: "rgba(151,187,205,0)",
              pointRadius: 0,
              order: 1,
            },
          ],
        },
        options: {
          responsive: true,
          lineTension: 1,
          legend: {
            display: false,
          },
          scales: {
            xAxes: [
              {
                type: "time",
                time: {
                  parser: timeFormat,
                },
                gridLines: {
                  // color: colors.mainLightGray,
                  display: true,
                },
                ticks: {
                  fontSize: 9,
                  maxTicksLimit: 6,
                  min: start,
                  max: end,
                  display: true,
                },
              },
            ],
            yAxes: [
              {
                gridLines: {
                  // color: colors.mainLightGray,
                  display: false,
                },
                ticks: {
                  callback: function(value: number) {
                    return value >= 1000 ? value / 1e3 + "T" : value;
                  },
                  max: max,
                  min: 0,
                  fontSize: 9,
                  maxTicksLimit: 4,
                  display: true,
                  padding: 1,
                },
              },
            ],
          },
        },
      };
    }
