public queue(key: number, buffer: Buffer): <mask> {
		let updated = false
		// Try and replace an existing queued image first
		for (const img of this.pendingImages) {
			if (img.key === key) {
				img.buffer = buffer
				updated = true
				break
			}
		}

		// If key isnt queued, then append
		if (!updated) {
			this.pendingImages.push({ key: key, buffer: buffer })
		}

		this.tryDequeue()
	}

