    arm1.current = new THREE.Vector3(8 * armLenFac, 0, 0);
    arm2.current = new THREE.Vector3(4 * armLenFac, 0, 0);
    arm3.current = new THREE.Vector3(1.5 * armLenFac, 0, 0);

    onReset();
