      mesh.current.rotation.x = Math.sin(clock.elapsedTime) * (Math.PI / 20);
      mesh.current.rotation.y = Math.cos(clock.elapsedTime) * (Math.PI / 20);
      mesh.current.scale.y = 0.9 + 0.1 * Math.sin(clock.elapsedTime);
